const listing = $('Enrich').item.json;
let triage = null;
try {
  const raw = $json.content && $json.content[0] && $json.content[0].text;
  if (raw) triage = JSON.parse(raw);
} catch (e) { triage = null; }
return [{ json: { ...listing, triage, fit_score: triage ? triage.fit_score : null } }];

const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const l = $('Merge triage').item.json;
const t = l.triage;
const score = (t && typeof t.fit_score === 'number') ? t.fit_score : 50;
const rent = l.rent_gross ?? l.rent_net;
const lines = [];
lines.push((score >= 80 ? '\u{1F4E2} ' : '\u{1F3E0} ') + '<b>' + esc(l.title) + '</b>');
lines.push((l.rooms ? l.rooms + ' pièces' : '? pièces') + (l.m2 ? ' · ' + l.m2 + ' m²' : '') + (rent ? ' · CHF ' + rent : '') + (l.commune ? ' · ' + esc(l.commune) : ''));
if (t) {
  lines.push('★ ' + score + '/100 · ' + esc(t.price_tier) + ' · ' + esc(t.condition) + ' · ' + esc(t.standard));
  if (t.summary_fr) lines.push(esc(t.summary_fr));
}
if (l.agency) lines.push('🏢 ' + esc(l.agency) + (l.agency_reputation ? ' — ' + esc(l.agency_reputation) : ''));
const feats = l.features ? Object.entries({balcon:l.features.balcony,ascenseur:l.features.elevator,parking:l.features.parking,'lave-linge':l.features.washingMachine,minergie:l.features.minergie,animaux:l.features.pets}).filter(e => e[1]).map(e => e[0]) : [];
if (feats.length) lines.push('✓ ' + feats.join(' · '));
if (l.url) lines.push('<a href="' + l.url + '">Voir l’annonce</a> · via ' + esc(l.source));
else lines.push('via ' + esc(l.source));
const photo = (Array.isArray(l.images) && l.images.length) ? l.images[0] : null;
return [{ json: { text: lines.join('\n'), photo } }];

// crossKey(listing) — coarse "blocking" fingerprint of a physical apartment, stable across
// portals despite address-formatting noise. It intentionally does NOT include rent: units in
// the same building share a key, and the cross-dup QUERY separates them with a rent tolerance
// (same building, different rent = different unit; same building, ~same rent = same flat on
// two portals). Returns null when there isn't enough to match on.
function crossKey(l) {
  const strip = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const commune = strip(l.commune).replace(/[^a-z0-9]+/g, '');
  const rooms = (l.rooms != null && !isNaN(l.rooms)) ? Number(l.rooms).toFixed(1) : null;
  if (!commune || !rooms) return null;

  const STREET = new Set(['rue','route','rte','avenue','av','ave','chemin','ch','impasse','imp',
    'place','pl','boulevard','bd','allee','quai','sentier','ruelle','esplanade','promenade',
    'clos','montee','passage','vieux','vieille','grand','grande']);
  const ART = new Set(['du','de','des','la','le','les','l','d','en','aux','au','sur','a']);
  const communeSet = new Set(strip(l.commune).split(/[^a-z0-9]+/).filter(Boolean));

  let addr = strip(l.address_raw).replace(/\b\d{4}\b/g, ' '); // drop NPA
  const tokens = addr.split(/[^a-z0-9]+/).filter(Boolean);
  const nums = tokens.filter(t => /^\d{1,3}$/.test(t));
  const number = nums.length ? nums[nums.length - 1] : null; // house number = last small number
  const streetToken = tokens.find(t =>
    /^[a-z]/.test(t) && !STREET.has(t) && !ART.has(t) && !communeSet.has(t)) || null;

  const rent = l.rent_gross ?? l.rent_net;
  const m2 = (l.m2 != null && !isNaN(l.m2)) ? Math.round(Number(l.m2)) : null;
  let geo = null;
  if (streetToken) geo = number ? streetToken + '-n' + number : streetToken;
  else if (m2) geo = 'm' + m2;              // sparse SMG alerts: no street/rent but have m²
  else if (rent != null) geo = 'r' + (Math.round(rent / 100) * 100);
  if (!geo) return null;
  return commune + '|' + rooms + '|' + geo;
}

const l = $json;
return [{ json: { ...l, cross_key: crossKey(l) } }];

const listing = $('Enrich').item.json;
const canon = ($json && $json.id) ? $json : null;
return [{ json: { ...listing, _dup_of: canon ? canon.id : null, _canonical: canon } }];
